#!/usr/bin/env node
/**
 * T15 — WOFF2 spike (plan §6, spec §7.1/§7.2, Appendix B).
 *
 * Question: does @pdf-lib/fontkit read Fontsource WOFF2 files and embed a subset
 * into a PDF generated by pdf-lib?
 *
 * Measurement, not optimism: every step is executed for real and every failure is
 * reported as it happened. The PDF stage runs in a child process because fontkit
 * throws its subsetting errors from a timer, which would otherwise abort this
 * script with an uncaught exception.
 *
 * Procedure:
 *   1. Load the temporarily installed pdf-lib and @pdf-lib/fontkit.
 *   2. Query the Fontsource API for Inter and Caveat and download the files through
 *      the URL model in src/config.js.
 *   3. fontkit.create(buffer), then measure a phrase with .layout().
 *   4. Build an A4 PDF with `subset: true`, write temp/spike-woff2.pdf, read it back.
 *   5. When the WOFF2 subset fails, repeat the same steps with the .woff files so the
 *      decision table in plan §6 can be applied with evidence, and embed WOFF2 with
 *      subset: false to show whether reading or subsetting is what breaks.
 *   6. Print a JSON report on stdout.
 *
 * Exit codes: 0 when the spike concludes (even when it concludes WOFF2 fails);
 * 1 only on a script or network error.
 *
 * Dependencies are installed with `npm install --no-save pdf-lib @pdf-lib/fontkit`
 * and never enter package.json.
 */
import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";

import { fonts as fontConfig } from "../src/config.js";

const execFileAsync = promisify(execFile);
const require = createRequire(import.meta.url);
const { PDFDocument, PDFDict, PDFName, rgb } = require("pdf-lib");
const fontkit = require("@pdf-lib/fontkit");

const SELF = fileURLToPath(import.meta.url);
const ROOT = resolve(dirname(SELF), "..");
const TEMP_DIR = resolve(ROOT, "temp");
const FONT_DIR = resolve(TEMP_DIR, "spike-fonts");
const PDF_STAGE_PAYLOAD = resolve(TEMP_DIR, "spike-pdf-stage.json");
const REQUEST_TIMEOUT_MS = 30000;
const PDF_STAGE_TIMEOUT_MS = 60000;

const INTER_PHRASE = "Formação, ação, coração, 100%";
const CAVEAT_PHRASE = "João";
const MEASURE_SIZE_PT = 10;
const A4 = { widthPt: 595.276, heightPt: 841.89 };

const TARGETS = [
  { fontId: "inter", subset: "latin", weight: 400, style: "normal", text: INTER_PHRASE },
  { fontId: "inter", subset: "latin-ext", weight: 400, style: "normal", text: INTER_PHRASE },
  { fontId: "inter", subset: "latin", weight: 700, style: "normal", text: INTER_PHRASE },
  { fontId: "inter", subset: "latin", weight: 400, style: "italic", text: INTER_PHRASE },
  { fontId: "caveat", subset: "latin", weight: 400, style: "normal", text: CAVEAT_PHRASE },
];

const PHASES = {
  woff2: { extension: "woff2", subset: true, pdfPath: resolve(TEMP_DIR, "spike-woff2.pdf") },
  woff: { extension: "woff", subset: true, pdfPath: resolve(TEMP_DIR, "spike-woff.pdf") },
  woff2NoSubset: {
    extension: "woff2",
    subset: false,
    pdfPath: resolve(TEMP_DIR, "spike-woff2-nosubset.pdf"),
  },
};

function log(message) {
  process.stderr.write(`${message}\n`);
}

function toRelative(pathname) {
  return relative(ROOT, pathname).replace(/\\/g, "/");
}

function fileName(target, extension) {
  return `${target.subset}-${target.weight}-${target.style}.${extension}`;
}

function buildUrl(version, target, extension) {
  return fontConfig.urlTemplate
    .replace("{base}", fontConfig.cdnBase)
    .replace("{id}", target.fontId)
    .replace("{version}", version)
    .replace("{subset}", target.subset)
    .replace("{weight}", String(target.weight))
    .replace("{style}", target.style)
    .replace(/\.woff2$/, `.${extension}`);
}

function sha256(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

async function fetchBuffer(url) {
  let timer = null;
  const timeout = new Promise((_resolve, reject) => {
    timer = setTimeout(
      () => reject(new Error(`timeout after ${REQUEST_TIMEOUT_MS} ms for ${url}`)),
      REQUEST_TIMEOUT_MS,
    );
  });
  try {
    const response = await Promise.race([fetch(url), timeout]);
    if (!response.ok) {
      throw new Error(`HTTP ${response.status} ${response.statusText} for ${url}`);
    }
    return Buffer.from(await response.arrayBuffer());
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Reads the Fontsource metadata of one family. jsDelivr serves `npmVersion`
 * (5.3.0); the API's `version` field is its own sequence number (v20, v23…).
 */
async function fetchFontMeta(fontId) {
  const apiUrl = `https://api.fontsource.org/v1/fonts/${fontId}`;
  const meta = JSON.parse((await fetchBuffer(apiUrl)).toString("utf8"));
  return {
    fontId,
    apiUrl,
    apiVersion: meta.version,
    npmVersion: meta.npmVersion,
    npmUrl: `https://www.npmjs.com/package/@fontsource/${fontId}/v/${meta.npmVersion}`,
    family: meta.family,
    category: meta.category,
    license: meta.license,
    subsets: meta.subsets,
    weights: meta.weights,
    styles: meta.styles,
    variants: meta.variants,
  };
}

function measureText(font, text, sizePt) {
  const run = font.layout(text);
  const unitsPerEm = font.unitsPerEm ?? null;
  const widthEm = unitsPerEm ? run.advanceWidth / unitsPerEm : null;
  const chars = [...text];
  const covered = chars.filter((char) => font.hasGlyphForCodePoint(char.codePointAt(0)));
  return {
    text,
    sizePt,
    advanceWidthUnits: run.advanceWidth,
    unitsPerEm,
    widthEm: widthEm === null ? null : Number(widthEm.toFixed(4)),
    widthPtAtSize: widthEm === null ? null : Number((widthEm * sizePt).toFixed(3)),
    characters: chars.length,
    coveredCharacters: covered.length,
    uncovered: chars
      .filter((char) => !font.hasGlyphForCodePoint(char.codePointAt(0)))
      .filter((char, index, list) => list.indexOf(char) === index),
  };
}

/** Downloads, parses and measures one target. Never throws for a font that fails. */
async function inspectTarget(target, meta, extension, subset) {
  const dir = resolve(FONT_DIR, extension, subset ? "subset" : "nosubset");
  const url = buildUrl(meta.npmVersion, target, extension);
  const filePath = resolve(dir, `${target.fontId}-${fileName(target, extension)}`);
  const apiVariantUrl =
    meta.variants?.[String(target.weight)]?.[target.style]?.[target.subset]?.url?.[extension] ??
    null;
  const entry = {
    fontId: target.fontId,
    family: meta.family,
    subset: target.subset,
    weight: target.weight,
    style: target.style,
    url,
    apiVariantUrl,
    urlMatchesApiVariant: null,
    file: null,
    bytes: null,
    sha256: null,
    parsed: false,
    fontName: null,
    unitsPerEm: null,
    numGlyphs: null,
    measure: null,
    error: null,
    downloadError: null,
    localPath: filePath,
  };

  let buffer;
  try {
    log(`download ${url}`);
    buffer = await fetchBuffer(url);
  } catch (error) {
    entry.downloadError = error.message;
    entry.error = error.message;
    return { entry, buffer: null };
  }

  entry.bytes = buffer.length;
  entry.sha256 = sha256(buffer);
  entry.urlMatchesApiVariant = apiVariantUrl === url;
  entry.file = toRelative(filePath);
  await mkdir(dir, { recursive: true });
  await writeFile(filePath, buffer);

  try {
    const font = fontkit.create(buffer);
    entry.parsed = true;
    entry.fontName = font.familyName ?? font.postscriptName ?? null;
    entry.unitsPerEm = font.unitsPerEm ?? null;
    entry.numGlyphs = font.numGlyphs ?? null;
    entry.measure = measureText(font, target.text, MEASURE_SIZE_PT);
  } catch (error) {
    entry.error = error.message;
  }

  return { entry, buffer };
}

/** Reads the fonts actually present in the saved PDF, through the pdf-lib API. */
function describePageFonts(reloaded, page) {
  const resources = page.node.Resources();
  if (!resources) return [];
  const fontDict = resources.lookupMaybe(PDFName.of("Font"), PDFDict);
  if (!fontDict) return [];
  const fonts = [];
  for (const [key] of fontDict.entries()) {
    const dict = fontDict.lookup(key, PDFDict);
    const baseFont = dict?.get(PDFName.of("BaseFont"))?.toString().replace(/^\//, "") ?? null;
    // pdf-lib names subset fonts "Family-Style-<number>" instead of writing the
    // six-letter prefix that other PDF producers use; both are recorded.
    const suffixMatch = baseFont?.match(/-(\d{3,})$/);
    fonts.push({
      resource: key.toString(),
      baseFont,
      subsetPrefix: baseFont && /^[A-Z]{6}\+/.test(baseFont) ? baseFont.slice(0, 6) : null,
      subsetSuffix: suffixMatch ? `-${suffixMatch[1]}` : null,
      toUnicode: Boolean(dict?.get(PDFName.of("ToUnicode"))),
    });
  }
  return fonts;
}

/** Runs the PDF stage in a child process so a fontkit timer crash is reported. */
async function runPdfStage(payload) {
  await writeFile(PDF_STAGE_PAYLOAD, JSON.stringify(payload, null, 2), "utf8");
  try {
    const { stdout } = await execFileAsync(
      process.execPath,
      [SELF, "--pdf-stage", PDF_STAGE_PAYLOAD],
      { timeout: PDF_STAGE_TIMEOUT_MS, maxBuffer: 1024 * 1024 },
    );
    const lastLine = stdout.trim().split("\n").filter(Boolean).at(-1) ?? "";
    return JSON.parse(lastLine);
  } catch (error) {
    const stderr = String(error.stderr ?? "").replace(/\r/g, "");
    const lines = stderr.split("\n").filter(Boolean);
    const reason =
      error.killed || error.signal === "SIGTERM"
        ? `timeout after ${PDF_STAGE_TIMEOUT_MS} ms`
        : (lines.find((line) => /^[A-Za-z]*Error:/.test(line.trim())) ??
          lines.find((line) => /Error/.test(line)) ??
          lines[0] ??
          "");
    return {
      ok: false,
      error: reason ? `child process failed: ${reason.trim()}` : "child process failed",
      exitCode: error.code ?? null,
      stderr: lines.slice(0, 10).join("\n"),
      pageFonts: [],
      subsetTags: [],
      toUnicodePresent: false,
    };
  }
}

function pickEntry(entries, fontId, weight, style, subset) {
  return (
    entries.find(
      (entry) =>
        entry.fontId === fontId &&
        entry.weight === weight &&
        entry.style === style &&
        entry.subset === subset &&
        entry.parsed,
    ) ?? null
  );
}

/** Builds the PDF stage payload for Inter latin 400/700 plus Caveat latin 400. */
function pdfPayload(entries, extension, subset, outPath) {
  const regular = pickEntry(entries, "inter", 400, "normal", "latin");
  const bold = pickEntry(entries, "inter", 700, "normal", "latin");
  const caveat = pickEntry(entries, "caveat", 400, "normal", "latin");
  return {
    format: extension,
    subset,
    outPath,
    fonts: [
      { role: "inter-400-normal-latin", path: regular?.localPath ?? null },
      { role: "inter-700-normal-latin", path: bold?.localPath ?? null },
      { role: "caveat-400-normal-latin", path: caveat?.localPath ?? null },
    ],
    lines: [
      { role: "inter-400-normal-latin", text: INTER_PHRASE, y: 760 },
      { role: "inter-700-normal-latin", text: INTER_PHRASE, y: 730 },
      { role: "caveat-400-normal-latin", text: CAVEAT_PHRASE, y: 700 },
    ],
  };
}

/** Child process: embed, draw, save and read back the PDF. */
async function pdfStage(payloadPath) {
  const payload = JSON.parse(await readFile(payloadPath, "utf8"));
  const result = {
    format: payload.format,
    subset: payload.subset,
    path: toRelative(payload.outPath),
    bytes: null,
    pages: null,
    widthPt: null,
    heightPt: null,
    reloaded: false,
    embedded: [],
    pageFonts: [],
    subsetTags: [],
    toUnicodePresent: false,
    notes: payload.subset
      ? "pdf-lib names subset fonts Family-Style-<number>; no six-letter prefix is written."
      : "Subsetting disabled: the whole font file is embedded.",
    ok: false,
    error: null,
  };

  const missing = payload.fonts.filter((font) => !font.path);
  if (missing.length > 0) {
    result.error = `Missing input fonts: ${missing.map((font) => font.role).join(", ")}`;
    process.stdout.write(`${JSON.stringify(result)}\n`);
    return;
  }

  const pdfDoc = await PDFDocument.create();
  pdfDoc.registerFontkit(fontkit);
  const loaded = new Map();
  for (const font of payload.fonts) {
    const bytes = await readFile(font.path);
    const embedded = await pdfDoc.embedFont(bytes, { subset: payload.subset });
    loaded.set(font.role, embedded);
    result.embedded.push({ role: font.role, ok: true });
  }

  const page = pdfDoc.addPage([A4.widthPt, A4.heightPt]);
  for (const line of payload.lines) {
    page.drawText(line.text, {
      x: 60,
      y: line.y,
      size: 18,
      font: loaded.get(line.role),
      color: rgb(0.1, 0.1, 0.1),
    });
  }

  pdfDoc.setTitle("LetterheadForge — spike WOFF2");
  pdfDoc.setProducer("LetterheadForge spike");
  pdfDoc.setCreator("LetterheadForge");

  const bytes = await pdfDoc.save();
  await writeFile(payload.outPath, bytes);
  result.bytes = bytes.length;

  const reloaded = await PDFDocument.load(bytes);
  const pages = reloaded.getPages();
  result.reloaded = true;
  result.pages = pages.length;
  if (pages.length > 0) {
    result.widthPt = Number(pages[0].getWidth().toFixed(3));
    result.heightPt = Number(pages[0].getHeight().toFixed(3));
    result.pageFonts = describePageFonts(reloaded, pages[0]);
  }
  result.subsetTags = result.pageFonts
    .map((font) => font.subsetPrefix ?? font.subsetSuffix)
    .filter(Boolean);
  result.toUnicodePresent =
    result.pageFonts.length > 0 && result.pageFonts.every((font) => font.toUnicode);
  result.ok = result.reloaded && result.pages === 1 && result.pageFonts.length === payload.fonts.length;

  process.stdout.write(`${JSON.stringify(result)}\n`);
}

/** One full measurement pass for a given format. */
async function runPhase(phaseName, metas) {
  const phase = PHASES[phaseName];
  const entries = [];
  const downloadFailures = [];

  for (const target of TARGETS) {
    const meta = metas[target.fontId];
    if (!meta) {
      entries.push({
        fontId: target.fontId,
        subset: target.subset,
        weight: target.weight,
        style: target.style,
        parsed: false,
        error: "Fontsource metadata unavailable",
        downloadError: "Fontsource metadata unavailable",
      });
      continue;
    }
    const { entry } = await inspectTarget(target, meta, phase.extension, phase.subset);
    entries.push(entry);
    if (entry.downloadError) downloadFailures.push(entry);
  }

  const parseOk = entries.every((entry) => entry.parsed);
  let pdf;
  if (parseOk) {
    log(`pdf stage (${phaseName}, subset=${phase.subset})`);
    pdf = await runPdfStage(pdfPayload(entries, phase.extension, phase.subset, phase.pdfPath));
  } else {
    pdf = {
      format: phase.extension,
      subset: phase.subset,
      ok: false,
      error: "PDF stage skipped: at least one file did not parse.",
      pageFonts: [],
      subsetTags: [],
      toUnicodePresent: false,
    };
  }

  const pdfOk = Boolean(pdf?.ok);
  const verdictPrefix = phase.subset ? phase.extension : `${phase.extension}-nosubset`;
  return {
    format: phase.extension,
    subset: phase.subset,
    files: entries,
    pdf,
    verdict: parseOk && pdfOk ? `${verdictPrefix}-ok` : `${verdictPrefix}-fail`,
    downloadFailures: downloadFailures.length,
    failures: entries.filter((entry) => !entry.parsed).map((entry) => ({
      fontId: entry.fontId,
      subset: entry.subset,
      weight: entry.weight,
      style: entry.style,
      error: entry.error,
    })),
  };
}

function publicReport(phase) {
  return {
    ...phase,
    files: phase.files.map((entry) => {
      const { localPath: _localPath, ...rest } = entry;
      return rest;
    }),
  };
}

async function main() {
  const argv = process.argv.slice(2);
  if (argv[0] === "--pdf-stage") {
    await pdfStage(argv[1]);
    return 0;
  }

  const startedAt = new Date();
  await mkdir(FONT_DIR, { recursive: true });

  const libraries = ["pdf-lib", "@pdf-lib/fontkit"].map((name) => {
    const pkg = require(`${name}/package.json`);
    return { name, version: pkg.version, license: pkg.license };
  });

  const metas = {};
  const metadataErrors = [];
  for (const fontId of ["inter", "caveat"]) {
    try {
      metas[fontId] = await fetchFontMeta(fontId);
    } catch (error) {
      metadataErrors.push({ fontId, error: error.message });
    }
  }

  const woff2 = await runPhase("woff2", metas);
  const fallback = woff2.verdict === "woff2-ok" ? null : await runPhase("woff", metas);
  const diagnostics = woff2.verdict === "woff2-ok" ? null : await runPhase("woff2NoSubset", metas);

  const failures = [
    ...woff2.failures,
    ...(woff2.pdf?.ok ? [] : [{ stage: "pdf", error: woff2.pdf?.error ?? "unknown error" }]),
  ];

  const report = {
    task: "T15",
    spike: "woff2",
    date: startedAt.toISOString().slice(0, 10),
    node: process.version,
    urlModel: fontConfig.urlTemplate.replace("{base}", fontConfig.cdnBase),
    measureSizePt: MEASURE_SIZE_PT,
    libraries,
    fonts: Object.values(metas).map((meta) => ({
      fontId: meta.fontId,
      family: meta.family,
      category: meta.category,
      apiVersion: meta.apiVersion,
      npmVersion: meta.npmVersion,
      npmUrl: meta.npmUrl,
      license: meta.license,
    })),
    metadataErrors,
    files: publicReport(woff2).files,
    pdf: woff2.pdf,
    verdict: woff2.verdict,
    failures,
    fallback: fallback ? publicReport(fallback) : null,
    diagnostics: diagnostics ? publicReport(diagnostics) : null,
  };

  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  return woff2.downloadFailures > 0 ? 1 : 0;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((error) => {
    process.stderr.write(`${JSON.stringify({ error: error.message, stack: error.stack }, null, 2)}\n`);
    process.exitCode = 1;
  });
